public static int longestLine(int[][] mat) {
    int m = mat.length;
    int n = mat[0].length;
    int longestLine = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            int currentLine = 1;
            while (i + currentLine < m && j + currentLine < n && mat[i + currentLine][j + currentLine] == 1) {
                currentLine++;
            }
            longestLine = Math.max(longestLine, currentLine);
        }
    }

    return longestLine;
}
