            if (i < rows && j < cols) {
                result[count] = mat[i][j];
                count++;
            }
        }
        for (int j = 1; j < rows; j++) {
            if (i + j < rows && (rows - j - 1) < cols) {
                result[count] = mat[i + j][rows - j - 1];
                count++;
            }
        }
        i++;
    }
    return result;
}
