public static int findSmallestInteger(int n) {
    int smallest = -1;
    int[] digits = toDigits(n);
    int[] sorted = sort(digits);
    for (int i = 0; i < sorted.length; i++) {
        int current = sorted[i];
        int swapIndex = findSwapIndex(sorted, current, i);
        if (swapIndex == -1) {
            continue;
        }
        int swapped = swap(current, sorted[swapIndex]);
        int rearranged = rearrangeDigits(sorted, swapped);
        if (rearranged > n && (smallest == -1 || rearranged < smallest)) {
            smallest = rearranged;
        }
    }
    return smallest;
}

private static int[] toDigits(int n) {
    if (n < 10) {
        return new int[] { n };
    }
    String num = String.valueOf(n);
    int[] digits = new int[num.length()];
    for (int i = 0; i < num.length(); i++) {
        digits[i] = Character.digit(num.charAt(i), 10);
    }
    return digits;
}

private static int[] sort(int[] digits) {
    Arrays.sort(digits);
    return digits;
}

private static int findSwapIndex(int[] digits, int current, int index) {
    for (int i = index + 1; i < digits.length; i++) {
        if (digits[i] < current) {
            return i;
        }
    }
    return -1;
}

private static int swap(int a, int b) {
    return (a > b) ? a + b : b + a;
}

private static int rearrangeDigits(int[] digits, int swapped) {
    String num = String.valueOf(swapped);
    int[] arrangedDigits = new int[num.length()];
    for (int i = 0; i < num.length(); i++) {
        arrangedDigits[i] = Character.digit(num.charAt(i), 10);
    }
    int result = 0;
    for (int digit : arrangedDigits) {
        result = result * 10 + digit;
    }
    return result;
}
