public static int calculateEnergy(String s) {
    int energy = 0;
    for (int i = 0; i < s.length(); i++) {
        char currentChar = s.charAt(i);
        int startIndex = i;
        int endIndex = i;
        while (endIndex < s.length() && s.charAt(endIndex) == currentChar) {
            endIndex++;
        }
        energy = Math.max(energy, endIndex - startIndex);
        i = endIndex - 1;
    }
    return energy;
}
